import os
root = r'${out}'
def files(top):
    out = {}
    for at, _, names in os.walk(top):
        for name in names:
            path = os.path.join(at, name)
            out[os.path.relpath(path, top)] = open(path, 'rb').read()
    return out
a, b = files(root + '/ds'), files(root + '/ds2')
diff = sorted(k for k in a if a[k] != b.get(k))
print('DS_REEXPORT', len(a), len(b), diff[:8])
assert len(a) == len(b) == 8 * 100 + 100 + 3 and not diff, (len(a), len(b), diff[:8])
